struct T *find(struct T *t, int k) {
  while (t && t->key != k) t = (k < t->key) ? t->left : t->right;
  return t;
}

struct T *insert(struct T *t, int k) {
  if (!t) return new_node(k);
  if (k < t->key) t->left = insert(t->left, k);
  else if (k > t->key) t->right = insert(t->right, k);
  return t;
}

bool ok(T *t, long lo, long hi) {
  return !t || (t->key > lo && t->key < hi && ok(t->left, lo, t->key) && ok(t->right, t->key, hi));
}
